namespace {
bool absoluteJournalDestination(const QString& path){
#ifdef Q_OS_WIN
 return QRegularExpression("^(?:[A-Za-z]:/|//[^/]+/[^/]+(?:/|$))").match(path).hasMatch();
#else
 return QDir::isAbsolutePath(path);
#endif
}
class SwitchDelegate final:public QStyledItemDelegate {
public: using QStyledItemDelegate::QStyledItemDelegate;
 void paint(QPainter* painter,const QStyleOptionViewItem& option,const QModelIndex& index)const override {
  painter->save();painter->fillRect(option.rect,option.state&QStyle::State_Selected?QColor("#12456a"):QColor("#08182a"));
  bool on=index.data(Qt::CheckStateRole).toInt()==Qt::Checked;QRect r=option.rect.adjusted(6,4,-6,-4);r.setWidth(qMin(72,r.width()));painter->setPen(on?QColor("#72ffb0"):QColor("#9cbed5"));painter->setBrush(on?QColor("#075736"):QColor("#23394c"));painter->drawRoundedRect(r,4,4);painter->drawText(r,Qt::AlignCenter,on?"ON":"OFF");painter->restore();
 }
 bool editorEvent(QEvent* event,QAbstractItemModel* model,const QStyleOptionViewItem&,const QModelIndex& index)override {
  if((event->type()==QEvent::MouseButtonRelease&&static_cast<QMouseEvent*>(event)->button()==Qt::LeftButton)||(event->type()==QEvent::KeyPress&&(static_cast<QKeyEvent*>(event)->key()==Qt::Key_Space||static_cast<QKeyEvent*>(event)->key()==Qt::Key_Select))){return model->setData(index,index.data(Qt::CheckStateRole).toInt()==Qt::Checked?Qt::Unchecked:Qt::Checked,Qt::CheckStateRole);}return false;
 }
};
}
